import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.55.0";

const URL = Deno.env.get('SUPABASE_URL') || '';
const KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || '';
const TOKEN = Deno.env.get('TELEGRAM_BOT_TOKEN') || Deno.env.get('BOT_TOKEN') || '';
const APP = 'https://t.me/Adsrewartsbot/app';
const sb = createClient(URL, KEY, { auth: { persistSession: false, autoRefreshToken: false } });
const json = (data:any,status=200)=>new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json'}});
const esc = (v:any)=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
const b = (text:string, callback_data:string)=>({text, callback_data});
const r = (...x:any[])=>x;
const fmt = (n:any)=>Number(n||0).toLocaleString('en-US');
const ist = (v:any)=>new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kolkata',day:'2-digit',month:'short',year:'numeric',hour:'numeric',minute:'2-digit',hour12:true}).format(new Date(v));

async function tg(method:string,payload:any){
  const res=await fetch(`https://api.telegram.org/bot${TOKEN}/${method}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
  const body=await res.json().catch(()=>({ok:false,description:'Bad Telegram response'}));
  if(!res.ok||!body.ok) throw new Error(body.description||`Telegram ${method} failed`);
  return body.result;
}
async function expectedSecret(){const{data}=await sb.rpc('get_bot_internal_secret',{p_name:'adsreward_telegram_webhook_secret'});return String(data||'')}
async function adminIds(){const{data}=await sb.from('settings').select('value').eq('key','bot_admin_telegram_ids').maybeSingle();return new Set(String(data?.value||Deno.env.get('ADMIN_TELEGRAM_ID')||'2139807311').split(',').map((x:string)=>Number(x.trim())).filter(Number.isSafeInteger))}
async function isAdmin(id:number){return (await adminIds()).has(id)}
async function sess(id:number){const{data}=await sb.from('admin_bot_sessions').select('state').eq('admin_telegram_id',id).maybeSingle();return data?.state||{}}
async function setSess(id:number,state:any){await sb.from('admin_bot_sessions').upsert({admin_telegram_id:id,state,updated_at:new Date().toISOString()},{onConflict:'admin_telegram_id'})}
async function clearSess(id:number){await setSess(id,{})}
async function audit(admin:number,action:string,targetUserId:string|null,details:any){await sb.from('admin_logs').insert({admin_telegram_id:admin,action,target_user_id:targetUserId,details})}
async function send(chat:number,text:string,kb:any[][]=[],messageId?:number){
  const payload:any={chat_id:chat,text,parse_mode:'HTML',disable_web_page_preview:true,reply_markup:{inline_keyboard:kb}};
  if(messageId){payload.message_id=messageId;try{return await tg('editMessageText',payload)}catch{delete payload.message_id}}
  return tg('sendMessage',payload);
}
async function ack(id:string,text=''){try{await tg('answerCallbackQuery',{callback_query_id:id,text})}catch{}}
const BACK=r(b('⬅️ Back','adm:main'));
const MAIN=[
  r(b('📊 Dashboard','adm:dashboard'),b('👥 Users','adm:users')),
  r(b('🎯 Tasks','adm:tasks'),b('🎁 Promo Codes','adm:promos')),
  r(b('💸 Withdrawals','adm:withdrawals'),b('📢 Broadcast','adm:broadcast')),
  r(b('🏆 Leaderboard','adm:leaderboard'),b('👥 Referrals','adm:referrals')),
  r(b('📺 Ads','adm:ads'),b('🎮 Rewards','adm:rewards')),
  r(b('🛡 Moderation','adm:moderation'),b('⚙️ Settings','adm:settings')),
  r(b('📜 Logs','adm:logs'),b('🔧 System','adm:system')),
];
async function c(table:string, fn?:(q:any)=>any){let q=sb.from(table).select('*',{count:'exact',head:true});if(fn)q=fn(q);const{count}=await q;return count||0}
async function sumBalances(){const{data}=await sb.from('balances').select('total_earned,total_withdrawn');return (data||[]).reduce((a:any,x:any)=>({earned:a.earned+Number(x.total_earned||0),withdrawn:a.withdrawn+Number(x.total_withdrawn||0)}),{earned:0,withdrawn:0})}
async function dashboard(chat:number,mid?:number){
  const start=new Date();start.setUTCHours(0,0,0,0);const day=start.toISOString();
  const vals=await Promise.all([
    c('users'),c('users',q=>q.gte('created_at',day)),c('users',q=>q.gte('last_active_at',day)),
    c('withdrawals',q=>q.eq('status','pending')),c('withdrawals',q=>q.eq('status','paid')),c('withdrawals',q=>q.eq('status','rejected')),
    c('ad_logs',q=>q.gte('created_at',day)),c('user_tasks',q=>q.gte('completed_at',day)),c('promo_claims',q=>q.gte('claimed_at',day)),
    c('referrals'),c('users',q=>q.eq('is_banned',true)),sumBalances()
  ]);
  const [total,newToday,active,pending,paid,rejected,ads,tasks,promos,refs,banned,bal]=vals as any;
  const text=`📊 <b>AdsReward Dashboard</b>\n\n👥 Total users: <b>${fmt(total)}</b>\n🆕 New today: ${fmt(newToday)}\n🟢 Active today: ${fmt(active)}\n\n💎 ADR issued: ${fmt(bal.earned)}\n💸 ADR withdrawn: ${fmt(bal.withdrawn)}\n⏳ Pending: ${pending} · ✅ Paid: ${paid} · ❌ Rejected: ${rejected}\n\n📺 Ads today: ${fmt(ads)}\n🎯 Tasks today: ${fmt(tasks)}\n🎁 Promo claims: ${fmt(promos)}\n👥 Referrals: ${fmt(refs)}\n🚫 Banned: ${fmt(banned)}`;
  return send(chat,text,[r(b('🔄 Refresh','adm:dashboard'),b('📈 Full Stats','adm:dashboard')),BACK],mid);
}
async function userSearchResults(chat:number,q:string,mid?:number){
  let query=sb.from('users').select('telegram_id,first_name,last_name,username,is_banned').limit(10);
  const cleaned=q.trim().replace(/^@/,'');const id=Number(cleaned);
  if(Number.isSafeInteger(id)&&id>0)query=query.eq('telegram_id',id);else query=query.or(`username.ilike.%${cleaned}%,first_name.ilike.%${cleaned}%,last_name.ilike.%${cleaned}%`);
  const{data}=await query;const kb=(data||[]).map((u:any)=>r(b(`${u.is_banned?'🚫 ':''}${[u.first_name,u.last_name].filter(Boolean).join(' ')}${u.username?' · @'+u.username:''}`,`adm:user:${u.telegram_id}`)));kb.push(BACK);
  return send(chat,data?.length?'👥 <b>User Search Results</b>':'No matching users.',kb,mid);
}
async function userView(chat:number,tid:number,mid?:number){
  const{data:u}=await sb.from('users').select('*').eq('telegram_id',tid).maybeSingle();if(!u)return send(chat,'User not found.',[BACK],mid);
  const [{data:bal},refs,tasks,ads,wds,promos]=await Promise.all([
    sb.from('balances').select('*').eq('user_id',u.id).maybeSingle(),c('referrals',q=>q.eq('referrer_id',u.id)),c('user_tasks',q=>q.eq('user_id',u.id)),c('ad_logs',q=>q.eq('user_id',u.id)),c('withdrawals',q=>q.eq('user_id',u.id)),c('promo_claims',q=>q.eq('user_id',u.id))
  ]);
  const text=`👤 <b>${esc([u.first_name,u.last_name].filter(Boolean).join(' ')||'User')}</b>${u.username?` · @${esc(u.username)}`:''}\nID: <code>${u.telegram_id}</code>\n\n💎 Balance: <b>${fmt(bal?.points)} ADR</b>\n📈 Total earned: ${fmt(bal?.total_earned)}\n💸 Total withdrawn: ${fmt(bal?.total_withdrawn)}\n👥 Referrals: ${refs}\n🎯 Tasks: ${tasks} · 📺 Ads: ${ads}\n🎁 Promo claims: ${promos} · 🧾 Withdrawals: ${wds}\n\n🚫 Banned: ${u.is_banned?'Yes':'No'}\n💸 Withdrawals disabled: ${u.withdrawals_disabled?'Yes':'No'}\n🎁 Rewards disabled: ${u.rewards_disabled?'Yes':'No'}\n👥 Referral rewards disabled: ${u.referral_rewards_disabled?'Yes':'No'}${u.admin_note?`\n📝 Note: ${esc(u.admin_note)}`:''}`;
  const kb=[
    r(b('➕ Add ADR',`adm:bal:add:${tid}`),b('➖ Deduct ADR',`adm:bal:deduct:${tid}`)),
    r(b(u.is_banned?'✅ Unban':'🚫 Ban',`adm:useract:ban:${tid}`),b('📝 Note',`adm:usernote:${tid}`)),
    r(b(u.withdrawals_disabled?'✅ Enable Withdraw':'⛔ Disable Withdraw',`adm:useract:withdraw:${tid}`),b(u.rewards_disabled?'✅ Enable Rewards':'⛔ Disable Rewards',`adm:useract:rewards:${tid}`)),
    r(b(u.referral_rewards_disabled?'✅ Enable Referral Rewards':'⛔ Disable Referral Rewards',`adm:useract:referral:${tid}`)),
    r(b('🔄 Refresh',`adm:user:${tid}`)),BACK
  ];
  return send(chat,text,kb,mid);
}
