async function promoView(chat:number,id:string,mid?:number){const{data:p}=await sb.from('promos').select('*').eq('id',id).maybeSingle();if(!p)return send(chat,'Promo not found.',[BACK],mid);const claims=await c('promo_claims',q=>q.eq('promo_id',id));const text=`🎁 <b>${esc(p.code)}</b>\n\nReward: ${fmt(p.reward_points)} ADR\nClaims: ${claims}/${p.max_claims}\nPer-user: ${p.per_user_limit}\nExpiry: ${p.expires_at?ist(p.expires_at):'Never'}\nActive: ${p.is_active?'Yes':'No'}`;return send(chat,text,[r(b(p.is_active?'⏸ Disable':'▶️ Enable',`adm:promo:toggle:${id}`),b('🗑 Delete','adm:promo:deleteask:'+id)),r(b('👥 Claimers','adm:promo:claimers:'+id)),r(b('⬅️ Promos','adm:promos'))],mid)}
