Deno.serve(async(req:Request)=>{
  try{
    if(req.method!=='POST')return json({handled:false});
    const secret=await expectedSecret();if(secret&&req.headers.get('x-telegram-bot-api-secret-token')!==secret)return json({handled:false,error:'unauthorized'},401);
    const u=await req.json().catch(()=>({}));const from=u.callback_query?.from||u.message?.from;if(!from)return json({handled:false});const admin=Number(from.id);if(!(await isAdmin(admin)))return json({handled:false});const chat=Number(u.callback_query?.message?.chat?.id||u.message?.chat?.id);if(!chat)return json({handled:false});
    if(u.callback_query&&String(u.callback_query.data||'').startsWith('adm:')){await handleCb(admin,chat,Number(u.callback_query.message.message_id),u.callback_query);return json({handled:true})}
    const text=String(u.message?.text||'');if(text==='/admin'||text.startsWith('/admin@')){await clearSess(admin);await send(chat,'🛠 <b>AdsReward Admin</b>\n\nComplete Telegram management panel.',MAIN);return json({handled:true})}
    const state=await sess(admin);if(state.flow){await handleText(admin,chat,u.message);return json({handled:true})}
    return json({handled:false});
  }catch(e){console.error('telegram-admin',e);return json({handled:true,error:(e as Error).message})}
});